-- Run only in a disposable database.
DROP MATERIALIZED VIEW IF EXISTS monthly_order_totals_demo;
CREATE MATERIALIZED VIEW monthly_order_totals_demo AS SELECT date_trunc('month', order_date) AS order_month, SUM(total_amount) AS revenue FROM orders GROUP BY date_trunc('month', order_date);
REFRESH MATERIALIZED VIEW monthly_order_totals_demo;
DROP MATERIALIZED VIEW monthly_order_totals_demo;
